					filename: cached.relativePath.split('/').pop() || '',
					relativePath: cached.relativePath,
					summary: cached.summary,
					keyFunctions: cached.keyFunctions,
					dependencies: cached.dependencies,
					exportedSymbols: cached.exportedSymbols,
